using System;
using System.Collections.Generic;
using System.Linq;
using Chaos.ArrayExtensions;
using Chaos.ListExtensions;
using UnityEngine;

public class Decoration
{
	public static List<Type> randomList;

	public bool spawnPrefab;

	public bool spawnPrefabOnEveryTile;

	public float spawnChance = 1f;

	protected AuxDeco[] auxDecos;

	protected bool auxDecosInitialized;

	protected bool shuffleAuxDecos;

	public int curWidth;

	public int curHeight;

	public int priority;

	public int maxSpawns = -1;

	public List<IntVec2> spawnPositions;

	public List<IntVec2> spawnOrigins;

	public float minDupeDistance;

	private static Dictionary<string, List<Vector2>> _globalSpawnPositions;

	private static Dictionary<string, List<Vector2>> _globalSpawnOrigins;

	public string globalSpawnGroup = string.Empty;

	public List<IGridDecorator> curGridDecoGroup;

	private List<Vector2> _invalidPositions;

	public GridDimensions dimensions;

	public bool dimensionsInitialized;

	public bool useMaxDimensions;

	internal GameObject prefab;

	public int prefabRowOffset;

	public int prefabColOffset;

	public float prefabWorldOffsetX;

	public float prefabWorldOffsetY;

	public GridDecoGroupManager gridDecoGroups;

	public List<TileGridTest> placementTests;

	public List<AutoTiler> autoTilers;

	public MapOrdinalDirections direction;

	protected AuxDeco[] AuxDecos
	{
		get
		{
			if (!auxDecosInitialized)
			{
				InitAuxDecos();
				auxDecosInitialized = true;
			}
			return auxDecos;
		}
	}

	public static Dictionary<string, List<Vector2>> GlobalSpawnPositions
	{
		get
		{
			if (_globalSpawnPositions == null)
			{
				_globalSpawnPositions = new Dictionary<string, List<Vector2>>();
			}
			return _globalSpawnPositions;
		}
	}

	public static Dictionary<string, List<Vector2>> GlobalSpawnOrigins
	{
		get
		{
			if (_globalSpawnOrigins == null)
			{
				_globalSpawnOrigins = new Dictionary<string, List<Vector2>>();
			}
			return _globalSpawnOrigins;
		}
	}

	protected List<Vector2> InvalidPositions
	{
		get
		{
			if (_invalidPositions == null)
			{
				_invalidPositions = new List<Vector2>();
			}
			return _invalidPositions;
		}
	}

	public int RowCount
	{
		get
		{
			return curHeight;
		}
		set
		{
			curHeight = value;
		}
	}

	public int ColCount
	{
		get
		{
			return curWidth;
		}
		set
		{
			curWidth = value;
		}
	}

	public Decoration(int newWidth = 0, int newHeight = 0, MapOrdinalDirections newDir = MapOrdinalDirections.SouthEast, GridDimensions newDimensions = null, float spawnChance = 1f)
	{
		curWidth = newWidth;
		curHeight = newHeight;
		direction = newDir;
		gridDecoGroups = new GridDecoGroupManager();
		placementTests = new List<TileGridTest>();
		autoTilers = new List<AutoTiler>();
		dimensions = newDimensions;
		this.spawnChance = spawnChance;
		if (dimensions == null)
		{
			dimensions = new GridDimensions(newHeight, newHeight, newWidth, newWidth);
		}
		spawnOrigins = new List<IntVec2>();
		spawnPositions = new List<IntVec2>();
	}

	public void InitDimensions()
	{
		if (dimensionsInitialized)
		{
			return;
		}
		if (gridDecoGroups.groups.Count == 0)
		{
			if (dimensions == null || dimensions.MaxRows == 0 || dimensions.MaxCols == 0 || dimensions.MinCols == 0 || dimensions.MinRows == 0)
			{
				throw new ArgumentNullException("Decorator's dimensions field is invalid and no GridDecoratorGroups are present to infer decoration's size from");
			}
		}
		else
		{
			dimensions = gridDecoGroups.dimensions;
			dimensionsInitialized = true;
		}
	}

	public bool IsDistanceValid(int row, int col)
	{
		for (int i = 0; i < spawnPositions.Count; i++)
		{
			if (IntVec2.Distance(spawnPositions[i], new IntVec2(row, col)) < minDupeDistance)
			{
				return false;
			}
		}
		return true;
	}

	public bool IsGlobalDistanceValid(Vector2 curPos)
