	public static void HandleMineCartSpawn(GameObject prefab, TileGrid tileGrid, int rowOrigin, int colOrigin, float prefabWorldOffsetX, float prefabWorldOffsetY, Transform parentTrans, Room room)
		if ((prefab == VertSectionPrefab || prefab == VertSectionEndBotPrefab) && Random.value > 0.25f)
			MineCartVertDeco mineCartVertDeco = new MineCartVertDeco();
			if (mineCartVertDeco.CanPlace(tileGrid, (int)((float)rowOrigin + prefabWorldOffsetY) - 3, (int)((float)colOrigin + prefabWorldOffsetX) - 1))
				mineCartVertDeco.Place(tileGrid, (int)((float)rowOrigin + prefabWorldOffsetY) - 3, (int)((float)colOrigin + prefabWorldOffsetX) - 1, parentTrans, room);
		else if (prefab == HorSectionPrefab && Random.value > 0.25f)
			MineCartHorDeco mineCartHorDeco = new MineCartHorDeco();
			if (mineCartHorDeco.CanPlace(tileGrid, (int)((float)rowOrigin + prefabWorldOffsetY) - 3, (int)((float)colOrigin + prefabWorldOffsetX) - 1))
				mineCartHorDeco.Place(tileGrid, (int)((float)rowOrigin + prefabWorldOffsetY) - 3, (int)((float)colOrigin + prefabWorldOffsetX) - 1, parentTrans, room);
