		north = (northEast = (east = (south = (southEast = (southWest = (west = (northWest = magnitude)))))));
	public OrdinalMagnitude(int north, int northEast, int east, int south, int southEast, int southWest, int west, int northWest)
		this.north = north;
		this.northEast = northEast;
		this.east = east;
